#include "history.h"
#include <stdlib.h>
static void stamp(time_t t,char *out,size_t size){struct tm *v=localtime(&t);if(v)strftime(out,size,"%Y-%m-%d %H:%M:%S",v);else snprintf(out,size,"unknown");}
void show_history(void){if(!head){puts("History is empty.");return;}size_t i=0;for(HistoryNode *p=head;p;p=p->next){char ts[32];stamp(p->visited_at,ts,sizeof ts);printf("%3zu. %-60s | %s%s\n",++i,p->url,ts,p==current?"  <-- CURRENT":"");}}
void delete_history_entry(void){if(!head){puts("History is empty.");return;}show_history();long choice;if(!read_number("Entry number to delete: ",&choice)){puts("Invalid number.");return;}if(choice<1||(size_t)choice>history_count){puts("Entry number out of range.");return;}HistoryNode *p=head;for(long i=1;i<choice;i++)p=p->next;int was_current=p==current;HistoryNode *replacement=p->next?p->next:p->prev;if(p->prev)p->prev->next=p->next;else head=p->next;if(p->next)p->next->prev=p->prev;else tail=p->prev;if(was_current)current=replacement;free(p);history_count--;if(!history_count)head=tail=current=NULL;printf("Deleted entry %ld.\n",choice);}
void show_statistics(void){size_t before=0,after=0,pos=0;int found=0;for(HistoryNode *p=head;p;p=p->next){if(p==current){found=1;pos=before+1;}else if(!found)before++;else after++;}printf("Total history entries: %zu\n",history_count);if(!current)puts("Current position: none");else printf("Current position: %zu of %zu\n",pos,history_count);printf("Back available: %s\n",current&&current->prev?"Yes":"No");printf("Forward available: %s\n",current&&current->next?"Yes":"No");printf("Pages before current: %zu\nPages after current: %zu\n",current?before:0,current?after:0);}
